// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address caller, uint256 warpTime) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.keeper());

        warpTime = bound(warpTime, 0, 365 days);
        vm.warp(warpTime);

        vm.prank(caller);
        bool ok = true;
        try c.executeBatchDeposit() {
            ok = false;
        } catch {}

        assertTrue(ok, "non-keeper executeBatchDeposit must revert");
    }
}
